from common import *
from verify import SQ
src('igeeks-v3'); dom('sql')
P="In PostgreSQL, what does the final query return?"
EMP="create table emp(id int primary key, name text, dept text, sal int);\ninsert into emp values (1,'Ann','IT',50),(2,'Bob','IT',70),(3,'Cy','HR',40),(4,'Di','HR',40),(5,'Ed',null,60);"
JN="create table d(id int primary key, name text);\ninsert into d values (1,'IT'),(2,'HR'),(3,'Ops');\ncreate table e(id int primary key, name text, d_id int references d(id), sal int);\ninsert into e values (1,'Ann',1,50),(2,'Bob',1,70),(3,'Cy',2,40),(4,'Di',2,40),(5,'Ed',null,60);"
SL="create table s(id int primary key, rep text, amt int);\ninsert into s values (1,'A',10),(2,'A',30),(3,'B',20),(4,'B',20),(5,'C',50);"
# ------------------------------------------------------------ beginner
topic('SELECT & Filtering')
M('b','k',"Which SQL statement retrieves rows from a table?","SELECT","GET","FETCH","READ","SELECT is the query statement. The others are not SQL statements for reading rows.")
M('b','k',"Which clause filters rows before they are returned?","WHERE","HAVING","GROUP BY","LIMIT","WHERE keeps only the rows that satisfy a condition. HAVING filters groups after aggregation.")
M('b','k',"Which keyword removes duplicate rows from a result?","DISTINCT","UNIQUE","DIFFERENT","SINGLE","SELECT DISTINCT returns each distinct row once.")
M('b','k',"Which clause sorts the result?","ORDER BY","SORT BY","GROUP BY","ARRANGE","ORDER BY sorts ascending by default. Add DESC for descending order.")
M('b','k',"Which operator matches a text pattern such as names starting with 'A'?","LIKE","MATCH","SIMILAR","EQUALS","name LIKE 'A%' matches values that start with A. % stands for any run of characters.")
M('b','k',"What does SELECT * FROM students return?","Every column of every row in students","Only the first row","Only the primary key column","The number of rows","The asterisk means all columns, and with no WHERE clause all rows are returned.")
topic('DDL & Constraints')
M('b','k',"Which statement adds new rows to a table?","INSERT","ADD","APPEND","UPDATE","INSERT INTO table (columns) VALUES (...) creates rows. UPDATE changes existing ones.")
M('b','k',"Which statement changes values in existing rows?","UPDATE","MODIFY","CHANGE","ALTER","UPDATE ... SET column = value [WHERE ...]. ALTER changes the table structure, not its rows.")
M('b','k',"Which constraint uniquely identifies each row and does not allow NULL?","PRIMARY KEY","FOREIGN KEY","CHECK","DEFAULT","A primary key is unique and not null. A table can have only one.")
topic('Aggregation & Grouping')
SQ('b','o',P,EMP,"select count(*) from emp;","5","4","6","1","COUNT(*) counts every row, and the table has 5 rows.")
SQ('b','o',P,EMP,"select max(sal) from emp;","70","60","50","240","MAX returns the largest salary, 70.")
SQ('b','o',P,EMP,"select count(dept) from emp;","4","5","2","1","COUNT(column) ignores NULLs. Ed has no department, so 4 values are counted.")
SQ('b','o',P,EMP,"select count(distinct dept) from emp;","2","4","3","5","The distinct non-null departments are IT and HR.")
SQ('b','o',P,EMP,"select sum(sal) from emp where dept = 'HR';","80","40","110","160","Cy and Di earn 40 each, so the sum is 80.")
SQ('b','o',P,EMP,"select (avg(sal))::int from emp where dept = 'IT';","60","50","70","120","The IT salaries are 50 and 70, whose average is 60.")
topic('SELECT & Filtering')
SQ('b','o',P,EMP,"select count(*) from emp where dept is null;","1","0","5","4","NULL cannot be compared with =. IS NULL finds the one row with no department.")
SQ('b','o',P,EMP,"select name from emp order by sal desc limit 1;","Bob","Ann","Ed","Cy","Sorting salaries from high to low and taking the first row gives Bob (70).")
SQ('b','o',P,"select 1;","select 'a' || 'b';","ab","a b","ba","a||b","|| concatenates strings in standard SQL and PostgreSQL.")
M('b','k',"Which clause groups rows so that aggregate functions work on each group?","GROUP BY","ORDER BY","PARTITION","COLLECT","GROUP BY puts rows with the same value in one group, and aggregates such as SUM are then computed per group.")
SQ('b','o',P,EMP,"select count(*) from emp where sal >= 50;","3","2","4","5","Ann (50), Bob (70) and Ed (60) earn at least 50.")
# ------------------------------------------------------------ intermediate
topic('Joins')
SQ('i','o',P,JN,"select count(*) from e join d on e.d_id = d.id;","4","5","3","15","An inner join drops Ed, who has no department. The other 4 employees match.")
SQ('i','o',P,JN,"select count(*) from e left join d on e.d_id = d.id;","5","4","3","15","A left join keeps every employee, including Ed, whose department columns are NULL.")
SQ('i','o',P,JN,"select d.name from d left join e on e.d_id = d.id where e.id is null;","Ops","HR","IT","Ed","A left join from d with e.id IS NULL finds departments with no employees. Only Ops has none.")
SQ('i','o',P,JN,"select count(*) from d cross join e;","15","8","5","3","A cross join pairs every row of d (3) with every row of e (5): 15 rows.")
M('i','k',"What is the difference between INNER JOIN and LEFT JOIN?","LEFT JOIN also keeps left-table rows that have no match","INNER JOIN keeps unmatched rows from both tables","LEFT JOIN only returns matching rows","There is no difference when a foreign key exists","INNER JOIN returns only matching pairs. LEFT JOIN adds the unmatched rows of the left table with NULLs on the right.")
topic('Subqueries, Windows & CTEs')
SQ('i','o',P,JN,"select count(*) from e where d_id not in (select id from d where name = 'IT');","2","3","4","5","d_id values not in {1} are 2 and 2 (Cy, Di). Ed's d_id is NULL, so NULL NOT IN (...) is unknown and he is excluded.")
SQ('i','o',P,JN,"select count(*) from (select sal from e union select sal from e) x;","4","10","5","2","UNION removes duplicates. The distinct salaries are 50, 70, 40 and 60. UNION ALL would keep all 10 rows.")
topic('Aggregation & Grouping')
SQ('i','o',P,JN,"select string_agg(d.name, ',' order by d.name) from (select d_id from e group by d_id having sum(sal) > 100) x join d on d.id = x.d_id;","IT","HR","IT,HR","Ops","HAVING keeps groups whose salary total exceeds 100. IT totals 120 and HR totals 80.")
SQ('i','o',P,JN,"select coalesce(max(sal), 0) from e where d_id = 3;","0","NULL","40","3","No employee is in department 3, so MAX is NULL. COALESCE replaces it with 0.")
SQ('i','o',P,JN,"select sum(case when sal >= 50 then 1 else 0 end) from e;","3","5","2","4","CASE gives 1 for salaries 50, 70 and 60, so the sum is 3.")
topic('SELECT & Filtering')
SQ('i','o',P,JN,"select count(*) from e where sal between 40 and 50;","3","2","4","1","BETWEEN is inclusive: 50, 40 and 40 qualify.")
SQ('i','o',P,JN,"select name from e where name like '_o%';","Bob","Ann","Cy","Ed","The pattern needs any single character, then 'o'. Only Bob matches.")
SQ('i','o',P,"select 1;","select length('database');","8","7","9","4","The word database has 8 characters.")
SQ('i','o',P,"select 1;","select substring('database' from 1 for 4);","data","base","datab","atab","substring from position 1 for 4 characters returns 'data'.")
topic('DDL & Constraints')
M('i','k',"What does a foreign key constraint enforce?","Referential integrity: values must exist in the referenced table","That the column is unique","That the column is never NULL","That the column is indexed automatically in every database","A foreign key prevents rows that point to a parent row that does not exist.")
topic('Normalization & Design')
M('i','k',"Which normal form removes partial dependencies on part of a composite key?","Second normal form (2NF)","First normal form (1NF)","Third normal form (3NF)","Boyce-Codd normal form (BCNF)","2NF requires every non-key attribute to depend on the whole key, not just a part of it.")
topic('Transactions & Concurrency')
M('i','k',"Which ACID property guarantees that committed data survives a system crash?","Durability","Atomicity","Consistency","Isolation","Durability means a committed transaction is not lost, usually through write-ahead logging.")
topic('DDL & Constraints')
M('i','k',"What is the main effect of adding an index to a column?","Faster lookups on that column at the cost of slower writes and more storage","Faster inserts and updates","The column becomes unique","The column can no longer contain NULL","An index is an extra structure that must be maintained on every write.")
SQ('i','o',P,JN,"select string_agg(name, ',' order by sal desc, name) from (select * from e order by sal desc, name limit 2) x;","Bob,Ed","Bob,Ann","Ed,Bob","Ann,Ed","The two highest salaries are Bob (70) and Ed (60).")
SQ('i','o',P,JN,"select count(*) from e where d_id is null or sal > 60;","2","1","3","5","Ed has no department and Bob earns 70, so two rows satisfy the OR condition.")
# ------------------------------------------------------------ advanced
topic('Subqueries, Windows & CTEs')
SQ('a','o',P,SL,"select string_agg(r::text, ',' order by id) from (select id, rank() over (order by amt desc) r from s) x;","5,2,3,3,1","4,2,3,3,1","5,2,3,4,1","1,2,3,3,5","Amounts in descending order are 50, 30, 20, 20, 10. The two 20s tie for rank 3 and the next rank is 5, leaving a gap.")
SQ('a','o',P,SL,"select string_agg(r::text, ',' order by id) from (select id, dense_rank() over (order by amt desc) r from s) x;","4,2,3,3,1","5,2,3,3,1","4,2,3,4,1","1,2,3,3,4","dense_rank does not leave gaps after ties, so the values 50, 30, 20, 10 rank 1, 2, 3, 4.")
SQ('a','o',P,SL,"select string_agg(rt::text, ',' order by id) from (select id, sum(amt) over (order by id) rt from s) x;","10,40,60,80,130","10,30,20,20,50","130,130,130,130,130","10,40,60,80,100","With ORDER BY the window sum is a running total: 10, 10+30, +20, +20, +50.")
SQ('a','o',P,SL,"select string_agg(rn::text, ',' order by id) from (select id, row_number() over (partition by rep order by id) rn from s) x;","1,2,1,2,1","1,2,3,4,5","1,1,1,1,1","2,1,2,1,1","row_number restarts at 1 for each rep: A has ids 1 and 2, B has 3 and 4, C has 5.")
SQ('a','o',P,SL,"select sum(coalesce(p, 0)) from (select lag(amt) over (order by id) p from s) x;","80","130","50","60","lag gives NULL, 10, 30, 20, 20. Treating NULL as 0 the total is 80.")
SQ('a','o',P,"select 1;","with recursive t(n) as (select 1 union all select n + 1 from t where n < 5) select sum(n) from t;","15","10","5","120","The recursive CTE produces 1 to 5, whose sum is 15.")
SQ('a','o',P,SL,"select count(*) from s a join s b on a.amt = b.amt and a.id < b.id;","1","2","0","4","Only ids 3 and 4 share an amount (20). The a.id < b.id condition counts the pair once.")
SQ('a','o',P,SL,"select count(*) from s where amt > (select avg(amt) from s);","2","3","1","5","The average is 26, so 30 and 50 are above it.")
SQ('a','o',P,SL,"select count(*) from s a where exists (select 1 from s b where b.rep = a.rep and b.id <> a.id);","4","5","2","3","Reps A and B each have two rows, so each of their 4 rows has another row with the same rep. C has only one.")
SQ('a','o',P,SL,"select string_agg(rep, ',' order by rep) from (select rep from s group by rep having sum(amt) >= 50) x;","C","A,B,C","A","B,C","The group totals are A = 40, B = 40, C = 50. Only C reaches 50.")
SQ('a','o',P,SL,"select count(*) from (select amt from s group by amt having count(*) > 1) x;","1","2","0","5","Only the amount 20 appears more than once.")
SQ('a','o',P,SL,"select max(amt) filter (where rep = 'A') from s;","30","50","40","10","FILTER restricts the aggregate to rep A rows (10 and 30), so MAX is 30.")
SQ('a','o',P,SL,"select string_agg(distinct rep, ',' order by rep) from s;","A,B,C","A,A,B,B,C","C,B,A","A","DISTINCT removes duplicate reps before they are joined into one string.")
SQ('a','o',P,SL,"select count(*) from (select id from s except select id from s where amt >= 30) x;","3","2","5","4","EXCEPT removes ids 2 and 5 (amounts 30 and 50) from the five ids, leaving 3.")
SQ('a','o',P,SL,"select coalesce(nullif(amt, 20), -1) from s where id = 3;","-1","20","NULL","0","NULLIF returns NULL when the two values are equal. COALESCE then replaces that NULL with -1.")
topic('Transactions & Concurrency')
M('a','k',"Which isolation level in the SQL standard prevents dirty reads, non-repeatable reads and phantom reads?","SERIALIZABLE","READ COMMITTED","READ UNCOMMITTED","REPEATABLE READ","Only SERIALIZABLE rules out all three anomalies in the standard. (PostgreSQL's REPEATABLE READ also avoids phantoms, but the standard does not require it.)")
M('a','k',"What is a deadlock?","Two or more transactions each wait for a lock held by another, so none can proceed","A transaction that runs for too long","A table that cannot be read","A failed COMMIT","The database detects the cycle and aborts one transaction so the others can continue.")
topic('DDL & Constraints')
M('a','k',"What is a covering index?","An index that contains every column a query needs, so the table need not be read","An index on the primary key","An index shared by two tables","A temporary index created by the optimiser","With a covering index the engine can answer the query from the index alone (an index-only scan).")
topic('Normalization & Design')
M('a','k',"What extra rule does Boyce-Codd normal form (BCNF) add to third normal form?","Every determinant must be a candidate key","No multi-valued attributes","No transitive dependencies on non-key attributes only","Every table must have a surrogate key","BCNF requires that whenever X determines Y, X must be a superkey. It fixes rare anomalies that 3NF allows.")
M('a','k',"A query filters WHERE LOWER(email) = 'a@x.com' on a large table with a normal index on email. Why might the index not be used?","The function on the column prevents a plain index lookup","LOWER is not a SQL function","Indexes only work on numbers","The index is too large","A plain index stores the raw values. Use an expression index on LOWER(email), or a case-insensitive type.")
M('a','k',"What does EXPLAIN ANALYZE show that EXPLAIN alone does not?","The actual run times and row counts from executing the query","The query's syntax errors","The table definitions","Which users have access","EXPLAIN shows the planned strategy. ANALYZE runs the query and reports real timings. Beware: it really executes data-changing statements.")
topic('Subqueries, Windows & CTEs')
M('a','k',"A column contains NULLs. What does WHERE col <> 5 do with rows where col is NULL?","Excludes them, because NULL <> 5 is unknown","Includes them, because NULL is not 5","Raises an error","Treats NULL as 0","Comparisons with NULL give unknown, and WHERE keeps only rows where the condition is true. Use IS DISTINCT FROM to include them.")
M('a','k',"What is the difference between UNION and UNION ALL?","UNION removes duplicate rows and UNION ALL keeps them","UNION ALL removes duplicates and UNION keeps them","UNION needs the same table and UNION ALL does not","They are identical","UNION ALL is faster because it skips the duplicate-removal step.")
